#include <iostream>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    int a = 0, b = 0;
    cout << "두 정수를 입력하세요 : ";
    cin >> a >> b;

    int iMax = a > b ? a : b;
    cout << "큰 값: " << iMax << endl;

    int iDiff = a > b ? a - b : b - a;
    cout << "차이: " << iDiff << endl;

    return 0;
}

