#include <iostream>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    int iNumber = 0;
    cout << "숫자를 입력하세요 : ";
    cin >> iNumber;
    cout << "입력한 숫자 " << iNumber << "은(는) ";

    cout << (0 <= iNumber && iNumber <= 9 ? "0 ~ 9 사이의 숫자입니다."
        : 10 <= iNumber && iNumber <= 19 ? "10 ~ 19 사이의 숫자입니다."
        : 20 <= iNumber && iNumber <= 29 ? "20 ~ 29 사이의 숫자입니다."
        : "그 외의 숫자입니다.") << endl;

    return 0;
}
